contract InvMutTest {
    C c;
    uint public calls;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        calls = 0;
        bool reverted;
        try c.transfer(from, address(this), _tos, v) { reverted = false; } catch { reverted = true; }
        assert(calls == _tos.length);
    }

    fallback() external payable {
        calls++;
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory _tos, uint v) public payable {
        require(_tos.length >= 2);
        // address(c) has no transferFrom function and no fallback, so every
        // low-level transferFrom call into it fails, making P revert for the
        // FULL list. M skips the last recipient, so it never attempts the
        // failing call for the final entry and returns true instead.
        bool reverted; try c.transfer(from, address(c), _tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public {
        require(true);
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool reverted;
        // address(this) has no transferFrom and its fallback reverts,
        // so every transferFrom attempt made by c fails.
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        // Rule: if the token address rejects every call, transfer must revert,
        // even for a single recipient (the loop must execute at least once).
        assert(reverted);
    }
    fallback() external payable {
        revert();
    }
    receive() external payable { revert(); }
}
